#include <numeric>
#include <vector>

long sum(const std::vector<long>& xs) {
    // the tail recursion over xs becomes the library's loop
    return std::accumulate(xs.begin(), xs.end(), 0L);
}

long step(long n, long acc) {
    if (n == 0) return acc;
    [[clang::musttail]] return step(n - 1, acc + n);  // build fails if not a tail call
}

